use std::error::Error;
use std::fs::File;
use std::io::{self, Write};
use std::path::PathBuf;

use clap::{Parser, ValueEnum};
use csv::{ReaderBuilder, StringRecord};
use unicode_segmentation::UnicodeSegmentation;
