        short = 't',
        long = "tsv",
        conflicts_with = "delimiter",
        help = "Use '\\t' as delimiter for tsv"
    )]
    tsv: bool,

    #[arg(
        short,
        long,
        value_name = "DELIMITER",
        default_value_t = ',',
        help = "Specify the field delimiter"
    )]
    delimiter: char,

    #[arg(
        short,
        long,
        value_name = "STYLE",
        default_value_t = Style::Sharp,
        help = "Specify the border style"
    )]
    style: Style,

    #[arg(
        short,
        long,
        value_name = "PADDING",
        default_value_t = 1_usize,
        help = "Specify padding for table cell"
    )]
    padding: usize,

    #[arg(
        short,
        long,
        value_name = "INDENT",
        default_value_t = 0_usize,
        help = "Specify global indent for table"
    )]
    indent: usize,

    #[arg(
        long,
        value_name = "LIMIT",
        default_value_t = 1000_usize,
        help = "Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit"
    )]
    sniff: usize,

    #[arg(
        long = "header-align",
        value_name = "HEADER_ALIGN",
        default_value_t = Align::Center,
        help = "Specify the alignment of the table header"
    )]
    header_align: Align,

    #[arg(
        long = "body-align",
        value_name = "BODY_ALIGN",
        default_value_t = Align::Left,
        help = "Specify the alignment of the table body"
    )]
    body_align: Align,

    #[arg(short = 'P', long = "disable-pager", help = "Disable pager")]
    disable_pager: bool,

    #[arg(value_name = "FILE", help = "File to view")]
    file: Option<PathBuf>,
}

#[derive(Clone, Copy)]
struct RuleStyle {
    left: char,
    center: char,
    right: char,
    fill: char,
}

#[derive(Clone, Copy)]
struct RowStyle {
    left: &'static str,
    center: &'static str,
    right: &'static str,
}

fn main() {
    if let Err(err) = run() {
        eprintln!("csview: {err}");
        std::process::exit(1);
    }
}

fn run() -> Result<(), Box<dyn Error>> {
    let cli = Cli::parse();
    let delimiter = if cli.tsv {
        b'\t'
    } else {
        cli.delimiter as u8
    };

    let mut reader = match &cli.file {
        Some(path) => ReaderBuilder::new()
            .delimiter(delimiter)
            .has_headers(!cli.no_headers)
            .from_reader(File::open(path)?),
        None => ReaderBuilder::new()
            .delimiter(delimiter)
            .has_headers(!cli.no_headers)
            .from_reader(io::stdin()),
    };

    let header = if cli.no_headers {
        None
    } else {
        Some(record_to_row(reader.headers()?, cli.number, Some("#".to_owned())))
    };

    let mut body = Vec::new();
    for (idx, record) in reader.records().enumerate() {
        let row_number = if cli.number {
            Some((idx + 1).to_string())
        } else {
            None
        };
        body.push(record_to_row(&record?, cli.number, row_number));
    }

    let output = render_table(&cli, header, body);
    io::stdout().write_all(output.as_bytes())?;
    Ok(())
}

fn record_to_row(record: &StringRecord, numbered: bool, row_number: Option<String>) -> Row {
    let mut row = Vec::with_capacity(record.len() + usize::from(numbered));
    if numbered {
        row.push(row_number.unwrap_or_default());
    }
    row.extend(record.iter().map(str::to_owned));
    row
}

fn render_table(cli: &Cli, header: Option<Row>, body: Vec<Row>) -> String {
    let mut widths = initial_widths(&header, &body, cli.number, cli.no_headers);
