+            print!("{HELP_TEXT}");
+        }
+        Ok(CliAction::Version) => {
+            print!("{VERSION_TEXT}");
+        }
+        Ok(CliAction::Run(cli)) => {
+            if let Err(err) = run(cli) {
+                eprintln!("csview: {err}");
+                std::process::exit(1);
+            }
+        }
+        Err(err) => {
+            eprint!("{}", err.message);
+            std::process::exit(2);
+        }
+    }
+}
+
+fn init_locale() {
+    let locale = CString::new("").expect("locale");
+    unsafe {
+        let _ = setlocale(6, locale.as_ptr());
+    }
+}
+
+fn parse_cli(args: &[String]) -> Result<CliAction, CliError> {
+    if args.iter().any(|arg| arg == "-h" || arg == "--help") {
+        return Ok(CliAction::Help);
+    }
+    if args.iter().any(|arg| arg == "-V" || arg == "--version") {
+        return Ok(CliAction::Version);
+    }
+
+    let mut cli = Cli {
+        no_headers: false,
+        number: false,
+        tsv: false,
+        delimiter: ',',
+        style: Style::Sharp,
+        padding: 1,
+        indent: 0,
+        sniff: 1000,
+        header_align: Align::Center,
+        body_align: Align::Left,
+        disable_pager: false,
+        file: None,
+    };
+
+    let mut delimiter_seen = false;
+    let mut i = 0;
+    let mut end_of_options = false;
+
+    while i < args.len() {
+        let arg = &args[i];
+
+        if end_of_options {
+            set_positional_file(&mut cli, arg)?;
+            i += 1;
+            continue;
+        }
+
+        if arg == "--" {
+            end_of_options = true;
+            i += 1;
+            continue;
+        }
+
+        if let Some(rest) = arg.strip_prefix("--") {
+            match rest {
+                "no-headers" => cli.no_headers = true,
+                "number" => cli.number = true,
+                "tsv" => cli.tsv = true,
+                "disable-pager" => cli.disable_pager = true,
+                "delimiter" => {
+                    let value = value_after_long(args, &mut i, "--delimiter <DELIMITER>")?;
+                    cli.delimiter = parse_delimiter(value)?;
+                    delimiter_seen = true;
+                }
+                "style" => {
+                    let value = value_after_long_with_possible(
+                        args,
+                        &mut i,
+                        "--style <STYLE>",
+                        STYLE_VALUES,
+                    )?;
+                    cli.style = parse_style(value)?;
+                }
+                "padding" => {
+                    let value = value_after_long(args, &mut i, "--padding <PADDING>")?;
+                    cli.padding = parse_usize(value, "--padding <PADDING>")?;
+                }
+                "indent" => {
+                    let value = value_after_long(args, &mut i, "--indent <INDENT>")?;
+                    cli.indent = parse_usize(value, "--indent <INDENT>")?;
+                }
+                "sniff" => {
+                    let value = value_after_long(args, &mut i, "--sniff <LIMIT>")?;
+                    cli.sniff = parse_usize(value, "--sniff <LIMIT>")?;
+                }
+                "header-align" => {
+                    let value = value_after_long_with_possible(
+                        args,
+                        &mut i,
+                        "--header-align <HEADER_ALIGN>",
+                        ALIGN_VALUES,
+                    )?;
+                    cli.header_align = parse_align(value, "--header-align <HEADER_ALIGN>")?;
+                }
+                "body-align" => {
+                    let value = value_after_long_with_possible(
+                        args,
+                        &mut i,
+                        "--body-align <BODY_ALIGN>",
+                        ALIGN_VALUES,
+                    )?;
+                    cli.body_align = parse_align(value, "--body-align <BODY_ALIGN>")?;
+                }
+                _ => return Err(unexpected_argument(arg, true)),
+            }
+            i += 1;
+            continue;
+        }
+
+        if arg.starts_with('-') && arg.len() > 1 {
+            let chars = arg[1..].chars().collect::<Vec<_>>();
+            let mut pos = 0;
+            while pos < chars.len() {
+                match chars[pos] {
+                    'H' => cli.no_headers = true,
+                    'n' => cli.number = true,
+                    't' => cli.tsv = true,
+                    'P' => cli.disable_pager = true,
+                    'd' => {
+                        let value = short_value(arg, pos + 1, args, &mut i, "-d <DELIMITER>")?;
+                        cli.delimiter = parse_delimiter(value)?;
+                        delimiter_seen = true;
+                        break;
+                    }
+                    's' => {
+                        let value = short_value(arg, pos + 1, args, &mut i, "-s <STYLE>")?;
+                        cli.style = parse_style(value)?;
+                        break;
+                    }
+                    'p' => {
+                        let value = short_value(arg, pos + 1, args, &mut i, "-p <PADDING>")?;
+                        cli.padding = parse_usize(value, "-p <PADDING>")?;
+                        break;
+                    }
+                    'i' => {
+                        let value = short_value(arg, pos + 1, args, &mut i, "-i <INDENT>")?;
+                        cli.indent = parse_usize(value, "-i <INDENT>")?;
+                        break;
+                    }
+                    _ => return Err(unexpected_argument(arg, true)),
+                }
+                pos += 1;
+            }
+            i += 1;
+            continue;
+        }
+
+        set_positional_file(&mut cli, arg)?;
+        i += 1;
+    }
+
+    if cli.tsv && delimiter_seen {
+        return Err(CliError {
+            message: String::from(
+                "error: the argument '--tsv' cannot be used with '--delimiter <DELIMITER>'\n\nUsage: executable --tsv [FILE]\n\nFor more information, try '--help'.\n",
+            ),
+        });
+    }
+
+    Ok(CliAction::Run(cli))
+}
+
+fn set_positional_file(cli: &mut Cli, arg: &str) -> Result<(), CliError> {
+    if cli.file.is_some() {
+        return Err(CliError {
+            message: format!(
+                "error: unexpected argument '{}' found\n\n{}\nFor more information, try '--help'.\n",
+                arg, USAGE_TEXT
+            ),
+        });
+    }
+    cli.file = Some(PathBuf::from(arg));
+    Ok(())
+}
+
+fn value_after_long<'a>(
+    args: &'a [String],
+    index: &mut usize,
+    spec: &str,
+) -> Result<&'a str, CliError> {
+    value_after_long_inner(args, index, spec, None)
+}
+
+fn value_after_long_with_possible<'a>(
+    args: &'a [String],
+    index: &mut usize,
+    spec: &str,
+    possible: &'static str,
+) -> Result<&'a str, CliError> {
+    value_after_long_inner(args, index, spec, Some(possible))
+}
+
+fn value_after_long_inner<'a>(
+    args: &'a [String],
+    index: &mut usize,
+    spec: &str,
+    possible: Option<&'static str>,
+) -> Result<&'a str, CliError> {
+    let next = args.get(*index + 1).ok_or_else(|| missing_value(spec, possible))?;
+    if next.starts_with('-') && next.len() > 1 {
+        return Err(unexpected_argument(next, true));
+    }
+    *index += 1;
+    Ok(next)
+}
+
+fn short_value<'a>(
+    arg: &'a str,
+    value_start: usize,
+    args: &'a [String],
+    index: &mut usize,
+    spec: &str,
+) -> Result<&'a str, CliError> {
+    if arg.len() > value_start + 1 {
+        return Ok(&arg[value_start + 1..]);
+    }
+
+    let next = args.get(*index + 1).ok_or_else(|| missing_value(spec, None))?;
+    if next.starts_with('-') && next.len() > 1 {
+        return Err(unexpected_argument(next, true));
+    }
+    *index += 1;
+    Ok(next)
+}
+
+fn missing_value(spec: &str, possible: Option<&'static str>) -> CliError {
+    let mut message = format!("error: a value is required for '{}' but none was supplied\n", spec);
+    if let Some(values) = possible {
+        message.push_str(&format!("  [possible values: {values}]\n"));
+    }
+    message.push_str("\nFor more information, try '--help'.\n");
+    CliError { message }
+}
+
+fn unexpected_argument(arg: &str, tip: bool) -> CliError {
+    let mut message = format!("error: unexpected argument '{}' found\n", arg);
+    if tip {
+        message.push_str(&format!(
+            "\n  tip: to pass '{}' as a value, use '-- {}'\n",
+            arg, arg
+        ));
+    }
+    message.push_str(&format!("\n{}\nFor more information, try '--help'.\n", USAGE_TEXT));
+    CliError { message }
+}
+
+fn invalid_value(
+    value: &str,
+    spec: &str,
+    reason: Option<&str>,
+    possible: Option<&'static str>,
+) -> CliError {
+    let mut message = format!("error: invalid value '{}' for '{}'", value, spec);
+    if let Some(reason) = reason {
+        message.push_str(&format!(": {reason}"));
+    }
+    message.push('\n');
+    if let Some(values) = possible {
+        message.push_str(&format!("  [possible values: {values}]\n"));
+    }
+    message.push_str("\nFor more information, try '--help'.\n");
+    CliError { message }
+}
+
+fn parse_delimiter(value: &str) -> Result<char, CliError> {
+    let mut chars = value.chars();
+    let first = chars.next().ok_or_else(|| {
+        invalid_value(
+            value,
+            "--delimiter <DELIMITER>",
+            Some("cannot parse char from empty string"),
+            None,
+        )
+    })?;
+    if chars.next().is_some() {
+        return Err(invalid_value(
+            value,
+            "--delimiter <DELIMITER>",
+            Some("too many characters in string"),
+            None,
+        ));
+    }
+    Ok(first)
+}
+
+fn parse_usize(value: &str, spec: &str) -> Result<usize, CliError> {
+    value
+        .parse::<usize>()
+        .map_err(|err| invalid_value(value, spec, Some(&err.to_string()), None))
+}
+
+fn parse_style(value: &str) -> Result<Style, CliError> {
+    match value {
+        "none" => Ok(Style::None),
+        "ascii" => Ok(Style::Ascii),
+        "ascii2" => Ok(Style::Ascii2),
+        "sharp" => Ok(Style::Sharp),
+        "rounded" => Ok(Style::Rounded),
+        "reinforced" => Ok(Style::Reinforced),
+        "markdown" => Ok(Style::Markdown),
+        "grid" => Ok(Style::Grid),
+        _ => Err(invalid_value(
+            value,
+            "--style <STYLE>",
+            None,
+            Some(STYLE_VALUES),
+        )),
+    }
+}
+
+fn parse_align(value: &str, spec: &str) -> Result<Align, CliError> {
+    match value {
+        "left" => Ok(Align::Left),
+        "center" => Ok(Align::Center),
+        "right" => Ok(Align::Right),
+        _ => Err(invalid_value(value, spec, None, Some(ALIGN_VALUES))),
+    }
+}
+
+fn run(cli: Cli) -> Result<(), Box<dyn Error>> {
+    let delimiter = if cli.tsv { b'\t' } else { cli.delimiter as u8 };
+    let mut input = Vec::new();
+    match &cli.file {
+        Some(path) => File::open(path)?.read_to_end(&mut input)?,
+        None => io::stdin().read_to_end(&mut input)?,
+    };
+
+    let parsed = parse_csv(&input, delimiter, cli.no_headers, cli.number)?;
+    let output = render_table(&cli, parsed.header, parsed.body);
+    io::stdout().write_all(output.as_bytes())?;
+    Ok(())
+}
+
+fn parse_csv(
+    input: &[u8],
+    delimiter: u8,
+    no_headers: bool,
+    number: bool,
+) -> Result<ParsedCsv, CsvError> {
+    let records = parse_records(input, delimiter);
+    if records.is_empty() {
+        let header = if no_headers {
+            None
+        } else if number {
+            Some(vec![String::from("#")])
+        } else {
+            Some(Vec::new())
+        };
+        return Ok(ParsedCsv {
+            header,
+            body: Vec::new(),
+        });
+    }
+
+    let expected = records[0].fields.len();
+    for record in records.iter().skip(1) {
+        if record.fields.len() != expected {
+            return Err(CsvError {
+                record: record.record_index,
+                line: record.line,
+                byte: record.byte,
+                found: record.fields.len(),
+                expected,
+            });
+        }
+    }
+
+    if no_headers {
+        let body = records
+            .into_iter()
+            .enumerate()
+            .map(|(idx, record)| {
+                let mut row = record.fields;
+                if number {
+                    row.insert(0, (idx + 1).to_string());
+                }
+                row
+            })
+            .collect::<Vec<_>>();
+        return Ok(ParsedCsv { header: None, body });
+    }
+
+    let mut iter = records.into_iter();
+    let mut header = iter.next().map(|record| record.fields).unwrap_or_default();
+    if number {
+        header.insert(0, String::from("#"));
+    }
+
+    let body = iter
+        .enumerate()
+        .map(|(idx, record)| {
+            let mut row = record.fields;
+            if number {
+                row.insert(0, (idx + 1).to_string());
+            }
+            row
+        })
+        .collect::<Vec<_>>();
+
+    Ok(ParsedCsv {
+        header: Some(header),
+        body,
+    })
+}
+
+fn parse_records(input: &[u8], delimiter: u8) -> Vec<ParsedRecord> {
+    let mut records = Vec::new();
+    let mut i = 0usize;
+    let mut line = 1usize;
+    let mut record_index = 1usize;
+
+    while i < input.len() {
+        if input[i] == b'\n' {
+            i += 1;
+            line += 1;
+            continue;
+        }
+        if input[i] == b'\r' {
+            if i + 1 < input.len() && input[i + 1] == b'\n' {
+                i += 2;
+            } else {
+                i += 1;
+            }
+            line += 1;
+            continue;
+        }
+
+        let start_byte = i;
+        let start_line = line;
+        let mut fields = Vec::new();
+        let mut field = Vec::new();
+        let mut in_quotes = false;
+        let mut at_field_start = true;
+
+        loop {
+            if i >= input.len() {
+                fields.push(String::from_utf8_lossy(&field).into_owned());
+                break;
+            }
+
+            let byte = input[i];
+
+            if at_field_start && byte == b'"' {
+                in_quotes = true;
+                at_field_start = false;
+                i += 1;
+                continue;
+            }
+
+            at_field_start = false;
+
+            if in_quotes {
+                if byte == b'"' {
+                    if i + 1 < input.len() && input[i + 1] == b'"' {
+                        field.push(b'"');
+                        i += 2;
+                    } else {
+                        in_quotes = false;
+                        i += 1;
+                    }
+                    continue;
+                }
+
+                field.push(byte);
+                if byte == b'\n' {
+                    line += 1;
+                }
+                i += 1;
+                continue;
+            }
+
+            if byte == delimiter {
+                fields.push(String::from_utf8_lossy(&field).into_owned());
+                field.clear();
+                at_field_start = true;
+                i += 1;
+                continue;
+            }
+
+            if byte == b'\n' {
+                fields.push(String::from_utf8_lossy(&field).into_owned());
+                i += 1;
+                line += 1;
+                break;
+            }
+
+            if byte == b'\r' {
+                fields.push(String::from_utf8_lossy(&field).into_owned());
+                if i + 1 < input.len() && input[i + 1] == b'\n' {
+                    i += 2;
+                } else {
+                    i += 1;
+                }
+                line += 1;
+                break;
+            }
+
+            field.push(byte);
+            i += 1;
+        }
+
+        if fields.len() == 1 && fields[0].is_empty() {
+            continue;
+        }
+
+        records.push(ParsedRecord {
+            fields,
+            record_index,
+            line: start_line,
+            byte: start_byte,
+        });
+        record_index += 1;
+    }
+
+    records
+}
+
+fn render_table(cli: &Cli, header: Option<Row>, body: Vec<Row>) -> String {
+    let mut widths = initial_widths(&header, &body, cli.number, cli.no_headers);
+    if let Some(row) = &header {
+        update_widths(&mut widths, row);
+    }
+    let sniff_limit = if cli.sniff == 0 {
+        body.len()
+    } else {
+        cli.sniff.min(body.len())
+    };
+    for row in body.iter().take(sniff_limit) {
+        update_widths(&mut widths, row);
+    }
+
+    let mut lines = Vec::new();
+    if let Some(rule) = top_rule(cli.style) {
+        lines.push(render_rule(&widths, cli.padding, rule));
+    }
+
+    if let Some(row) = &header {
+        lines.push(render_row(
+            row,
+            &widths,
+            cli.padding,
+            cli.header_align,
+            cli.style,
+        ));
+        if !body.is_empty() {
+            if let Some(rule) = middle_rule(cli.style) {
+                lines.push(render_rule(&widths, cli.padding, rule));
+            }
+        }
+    }
+
+    for (idx, row) in body.iter().enumerate() {
+        lines.push(render_row(
+            row,
+            &widths,
+            cli.padding,
+            cli.body_align,
+            cli.style,
+        ));
+        if cli.style == Style::Grid && idx + 1 < body.len() {
+            if let Some(rule) = middle_rule(cli.style) {
+                lines.push(render_rule(&widths, cli.padding, rule));
+            }
+        }
+    }
+
+    if let Some(rule) = bottom_rule(cli.style) {
+        lines.push(render_rule(&widths, cli.padding, rule));
+    }
+
+    if lines.is_empty() {
+        return String::new();
+    }
+
+    let indent = " ".repeat(cli.indent);
+    let mut output = lines
+        .into_iter()
+        .map(|line| format!("{indent}{line}"))
+        .collect::<Vec<_>>()
+        .join("\n");
+    output.push('\n');
+    output
+}
+
+fn initial_widths(header: &Option<Row>, body: &[Row], number: bool, no_headers: bool) -> Vec<usize> {
+    if let Some(row) = header {
+        return vec![0; row.len()];
+    }
+    if let Some(row) = body.first() {
+        return vec![0; row.len()];
+    }
+    if number && no_headers {
+        return vec![1];
+    }
+    Vec::new()
+}
+
+fn update_widths(widths: &mut [usize], row: &[String]) {
+    for (width, cell) in widths.iter_mut().zip(row.iter()) {
+        *width = (*width).max(display_width(cell));
+    }
+}
+
+fn display_width(value: &str) -> usize {
+    value.chars().map(char_width).sum()
+}
+
+fn char_width(ch: char) -> usize {
+    match ch {
+        '\n' | '\r' | '\t' => 1,
+        _ => {
+            let width = unsafe { wcwidth(ch as c_int) };
+            if width < 0 {
+                0
+            } else {
+                width as usize
+            }
+        }
+    }
+}
+
+fn truncate_to_width(value: &str, limit: usize) -> String {
+    if display_width(value) <= limit {
+        return value.to_owned();
+    }
+
+    let mut width = 0;
+    let mut out = String::new();
+    for ch in value.chars() {
+        let ch_width = char_width(ch);
+        if width + ch_width > limit {
+            break;
+        }
+        out.push(ch);
+        width += ch_width;
+    }
+    out
+}
+
+fn format_cell(value: &str, width: usize, padding: usize, align: Align) -> String {
+    let value = truncate_to_width(value, width);
+    let slack = width.saturating_sub(display_width(&value));
+    let (left_extra, right_extra) = match align {
+        Align::Left => (0, slack),
+        Align::Center => (slack / 2, slack - (slack / 2)),
+        Align::Right => (slack, 0),
+    };
+
+    format!(
+        "{}{}{}",
+        " ".repeat(padding + left_extra),
+        value,
+        " ".repeat(padding + right_extra)
+    )
+}
+
+fn render_row(row: &[String], widths: &[usize], padding: usize, align: Align, style: Style) -> String {
+    let cells = row
+        .iter()
+        .zip(widths.iter().copied())
+        .map(|(cell, width)| format_cell(cell, width, padding, align))
+        .collect::<Vec<_>>();
+
+    match row_style(style) {
+        Some(parts) => format!("{}{}{}", parts.left, cells.join(parts.center), parts.right),
+        None => cells.join(""),
+    }
+}
+
+fn render_rule(widths: &[usize], padding: usize, style: RuleStyle) -> String {
+    let segments = widths
+        .iter()
+        .map(|width| std::iter::repeat(style.fill).take(width + (padding * 2)).collect::<String>())
+        .collect::<Vec<_>>();
+    format!(
+        "{}{}{}",
+        style.left,
+        segments.join(&style.center.to_string()),
+        style.right
+    )
+}
+
+fn row_style(style: Style) -> Option<RowStyle> {
+    match style {
+        Style::None => None,
+        Style::Ascii => Some(RowStyle {
+            left: "|",
+            center: "|",
+            right: "|",
+        }),
+        Style::Ascii2 => Some(RowStyle {
+            left: " ",
+            center: "|",
+            right: " ",
+        }),
+        Style::Sharp | Style::Rounded | Style::Reinforced | Style::Grid => Some(RowStyle {
+            left: "│",
+            center: "│",
+            right: "│",
+        }),
+        Style::Markdown => Some(RowStyle {
+            left: "|",
+            center: "|",
+            right: "|",
+        }),
+    }
+}
+
+fn top_rule(style: Style) -> Option<RuleStyle> {
+    match style {
+        Style::None | Style::Ascii2 | Style::Markdown => None,
+        Style::Ascii => Some(RuleStyle {
+            left: '+',
+            center: '+',
+            right: '+',
+            fill: '-',
+        }),
+        Style::Sharp | Style::Grid => Some(RuleStyle {
+            left: '┌',
+            center: '┬',
+            right: '┐',
+            fill: '─',
+        }),
+        Style::Rounded => Some(RuleStyle {
+            left: '╭',
+            center: '┬',
+            right: '╮',
+            fill: '─',
+        }),
+        Style::Reinforced => Some(RuleStyle {
+            left: '┏',
+            center: '┬',
+            right: '┓',
+            fill: '─',
+        }),
+    }
+}
+
+fn middle_rule(style: Style) -> Option<RuleStyle> {
+    match style {
+        Style::None => None,
+        Style::Ascii => Some(RuleStyle {
+            left: '+',
+            center: '+',
+            right: '+',
+            fill: '-',
+        }),
+        Style::Ascii2 => Some(RuleStyle {
