  -p, --padding <PADDING>
          Specify padding for table cell [default: 1]
  -i, --indent <INDENT>
          Specify global indent for table [default: 0]
      --sniff <LIMIT>
          Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit
          [default: 1000]
      --header-align <HEADER_ALIGN>
          Specify the alignment of the table header [default: center] [possible values: left,
          center, right]
      --body-align <BODY_ALIGN>
          Specify the alignment of the table body [default: left, center,
          right]
  -P, --disable-pager
          Disable pager
  -h, --help
          Print help
  -V, --version
          Print version
";

const VERSION_TEXT: &str = "csview 1.3.4\n";
const USAGE_TEXT: &str = "Usage: executable [OPTIONS] [FILE]\n";
const STYLE_VALUES: &str = "none, ascii, ascii2, sharp, rounded, reinforced, markdown, grid";
const ALIGN_VALUES: &str = "left, center, right";

type Row = Vec<String>;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Align {
    Left,
    Center,
    Right,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Style {
    None,
