}

unsafe extern "C" {
    fn setlocale(category: c_int, locale: *const c_char) -> *mut c_char;
    fn wcwidth(ch: c_int) -> c_int;
}

fn main() {
    init_locale();

    let args = std::env::args().skip(1).collect::<Vec<_>>();
    match parse_cli(&args) {
        Ok(CliAction::Help) => {
            print!("{HELP_TEXT}");
        }
        Ok(CliAction::Version) => {
            print!("{VERSION_TEXT}");
        }
        Ok(CliAction::Run(cli)) => {
